"""Second question types for the Chemistry Olympiad framework (CO). Each objective's first item is the forward calculation
or fact; these ask it in reverse, as a scaling or comparison, or about a neighbouring quantity of the same model. Written
from scratch (USNCO questions are ACS's, never copied)."""
from opl_dsl import Q

FILE, FRAMEWORK = "co-second-types", "chemistry-olympiad"
MC = ["{{o1}}", "{{o2}}", "{{o3}}", "{{o4}}"]
n = lambda v: f"nsimplify({v})"
R, R_ = "8.314462618", "Rational('8.314462618')"
F, F_ = "96485.33212", "Rational('96485.33212')"
RL, RL_ = "0.082057", "Rational('0.082057')"
H, H_ = "6.62607015e-34", "Rational('6.62607015e-34')"
C, C_ = "299792458", "Integer(299792458)"
NA, NA_ = "6.02214076e23", "Rational('6.02214076e23')"
KB, KB_ = "1.380649e-23", "Rational('1.380649e-23')"


def facts(name, skill, rows, explain):
    return Q(name, skill, "{{q}}", pace="recall", cases=[{"q": q, "o1": a, "o2": b, "o3": c, "o4": d} for q, a, b, c, d in rows],
             choice=MC, correct="0", verify="authored", explain=explain)


def mc(name, skill, prompt, cases, explain, pace="quick"):
    """multiple choice whose options are case fields o1 (right) … o4"""
    return Q(name, skill, prompt, pace=pace, cases=cases, choice=MC, correct="0", verify="authored", explain=explain)


